insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('ab222b1e-0804-41c6-b13e-8fa91668bc07', '002fe60a-3c5c-4331-854c-ffeae35c06f6', $$in 2020 is een nieuw belastingstelsel ingevoerd: belasting op arbeid omlaag, op consumptie omhoog$$,
   $$economie-havo-2022-iii-van-drie-naar-twee-schijven-context1.png$$,
   $$In 2020 is een nieuw belastingstelsel ingevoerd in Nederland. Het belangrijkste doel van de hervorming is om werken meer lonend te maken. Daarom is de belasting op arbeid verlaagd en de belasting op consumptie verhoogd. Het nieuwe stelsel bevat de volgende maatregelen:$$, 'inline'),
  ('95a8324c-1309-4919-8ede-a5db33e42dc8', '002fe60a-3c5c-4331-854c-ffeae35c06f6', $$de vier maatregelen van het nieuwe stelsel (schijven, heffingskortingen, hypotheekrenteaftrek, btw)$$,
   $$economie-havo-2022-iii-van-drie-naar-twee-schijven-context2.png$$,
   $$1 Het aantal belastingschijven is teruggebracht van drie naar twee met aanpassing van de marginale belastingtarieven (zie bron 1).
2 Tegelijkertijd veranderde de hoogte van de arbeidskorting en de algemene heffingskorting (zie bron 2).
3 De hypotheekrenteaftrek1) wordt verlaagd naar het tarief in de eerste schijf.
4 Het lage btw-tarief2) is verhoogd van 6 naar 9 procent. De overige btw- tarieven blijven ongewijzigd.$$, 'inline'),
  ('732d6b5e-79ac-4496-b140-b7dec044c355', '002fe60a-3c5c-4331-854c-ffeae35c06f6', $$noten bij hypotheekrenteaftrek en het lage btw-tarief$$,
   $$economie-havo-2022-iii-van-drie-naar-twee-schijven-context3.png$$,
   $$noot 1 Hypotheekrenteaftrek is een aftrekpost voor de inkomstenbelasting: de betaalde hypotheekrente voor de eigen woning mag onder voorwaarden afgetrokken worden van het bruto-inkomen om het belastbaar inkomen te bepalen. noot 2 Het lage btw-tarief is het tarief dat geheven wordt op de eerste levensbehoeften en op arbeidsintensieve diensten zoals die van de kapper, schilder en fietsenmaker.$$, 'inline'),
  ('c3a45791-44b5-4327-9551-b81ab9bc27cf', '002fe60a-3c5c-4331-854c-ffeae35c06f6', $$gemiddelde belastingdruk bij € 40.000 was in het oude systeem 27,9%$$,
   $$economie-havo-2022-iii-van-drie-naar-twee-schijven-context4.png$$,
   $$Een medewerker van een politieke partij wil nagaan of de gemiddelde belastingdruk op arbeid bij werknemers in de middengroep inderdaad daalt onder het nieuwe inkomstenbelastingstelsel. De medewerker berekent dat bij een belastbaar inkomen uit arbeid van € 40.000 en zonder aftrekposten, de gemiddelde belastingdruk bij het oude belastingsysteem 27,9% was.$$, 'inline'),
  ('ec046127-6753-4f6c-a290-5502c5543040', '002fe60a-3c5c-4331-854c-ffeae35c06f6', $$formule gemiddelde belastingdruk$$,
   $$economie-havo-2022-iii-van-drie-naar-twee-schijven-context5.png$$,
   $$De gemiddelde belastingdruk = (te betalen belasting / belastbaar inkomen) × 100%$$, 'inline'),
  ('9fc2964d-f810-42d4-a722-bca97f1f4da3', '002fe60a-3c5c-4331-854c-ffeae35c06f6', $$CPB: stijging reëel arbeidsinkomen en werkgelegenheid, daling werkloosheid$$,
   $$economie-havo-2022-iii-van-drie-naar-twee-schijven-context6.png$$,
   $$Uit de doorrekening van het nieuwe belastingstelsel door het Centraal Planbureau (CPB) blijkt dat de maatregelen zorgen voor:
− een gemiddelde stijging van het reëel arbeidsinkomen;
− een stijging van de werkgelegenheid;
− een daling van de werkloosheid.$$, 'inline'),
  ('c63158ca-a59a-4c8a-a870-e761cbf98f08', '002fe60a-3c5c-4331-854c-ffeae35c06f6', $$een econoom: de werkloosheid daalt minder sterk dan de werkgelegenheid stijgt$$,
   $$economie-havo-2022-iii-van-drie-naar-twee-schijven-context7.png$$,
   $$Door de toegenomen vraag naar arbeid daalt de werkloosheid. Een econoom stelt: “De daling van de werkloosheid als gevolg van het nieuwe belastingstelsel is minder sterk dan de stijging van de werkgelegenheid.”$$, 'inline'),
  ('62bb32ad-9afa-442a-bdb5-5384b10fc4f8', '002fe60a-3c5c-4331-854c-ffeae35c06f6', $$verhoging van het lage btw-tarief van 6 naar 9 procent; verdeling consumptieve bestedingen over de tarieven$$,
   $$economie-havo-2022-iii-van-drie-naar-twee-schijven-context8.png$$,
   $$Over de verhoging van het lage btw-tarief van 6 naar 9 procent ontstond direct veel discussie in de media. De koopkracht zou dalen als gevolg van toegenomen inflatie. Uit onderzoek van het CPB blijkt dat:
− 20% van alle consumptieve bestedingen valt onder het huidige lage tarief van 6%;
− 40% van alle consumptieve bestedingen valt onder het hoge tarief van 21%;
− 40% van alle consumptieve bestedingen valt onder het tarief van 0%.$$, 'inline'),
  ('cc5196a7-8b00-43f1-a462-ad69bb261e61', '002fe60a-3c5c-4331-854c-ffeae35c06f6', $$bron 1: schijvenstelsels van het oude en het nieuwe belastingsysteem$$,
   $$economie-havo-2022-iii-van-drie-naar-twee-schijven-context9.png$$,
   $$bron 1 schijvenstelsels van het oude en het nieuwe belastingsysteem
oud belastingsysteem: schijf 1 € 0 − € 20.142: 36,55% | schijf 2 € 20.143 − € 68.600: 40,85% | schijf 3 € 68.601 en hoger: 51,95%
nieuw belastingsysteem: schijf 1 € 0 − € 68.600: 36,93% | schijf 2 € 68.601 en hoger: 49,50%$$, 'inline'),
  ('ad8d21ab-7f4d-42fd-a4ab-7fa835d030d6', '002fe60a-3c5c-4331-854c-ffeae35c06f6', $$bron 2: heffingskortingen van het oude en het nieuwe belastingsysteem$$,
   $$economie-havo-2022-iii-van-drie-naar-twee-schijven-context10.png$$,
   $$bron 2 heffingskortingen van het oude en het nieuwe belastingsysteem
belastbaar inkomen | oud: algemene heffingskorting ; arbeidskorting | nieuw: algemene heffingskorting ; arbeidskorting
€ 0 − € 20.000 | € 2.265 ; € 3.153 | € 2.382 ; € 3.211
€ 20.001 − € 40.000 | € 1.336 ; € 2.978 | € 1.406 ; € 2.857
€ 40.001 − € 60.000 | € 399 ; € 2.258 | € 423 ; € 1.657
€ 60.001 − € 80.000 | € 0 ; € 1.538 | € 0 ; € 457
€ 80.001 − € 100.000 | € 0 ; € 818 | € 0 ; € 0
€ 100.001 en hoger | € 0 ; € 0 | € 0 ; € 0$$, 'inline'),
  ('f8692c78-4550-4103-929e-c15f646272a1', '137eda5a-bf04-404b-969b-7af10af4d66c', $$de huisvuilophaaldienst van Voordonk heeft een wettelijk monopolie en werkt niet kostendekkend$$,
   $$economie-havo-2022-iii-huisvuil-ophalen-kan-goedkoper-context1.png$$,
   $$De huisvuilophaaldienst van de gemeente Voordonk heeft een wettelijk monopolie op het ophalen van huisvuil bij de 2.500 huishoudens in de gemeente. De huisvuilophaaldienst slaagt er op dit moment niet in om kostendekkend te werken. De jaarlijkse kosten en opbrengsten van het ophalen van huisvuil door de dienst zijn:$$, 'inline'),
  ('b46cd341-3ccd-452f-a4b9-7990d97258b3', '137eda5a-bf04-404b-969b-7af10af4d66c', $$tabel: jaarlijkse kosten en opbrengsten van het ophalen van huisvuil$$,
   $$economie-havo-2022-iii-huisvuil-ophalen-kan-goedkoper-context2.png$$,
   $$Gemeentelijke heffing voor het ophalen van huisvuil: € 300 per huishouden, per jaar
Loonkosten twee werknemers: 2 x € 40.000 = € 80.000 per jaar
Afschrijving vrachtwagen: € 50.000 per jaar
Gemiddelde kosten voor brandstof, reiniging en onderhoud vrachtwagen: € 130 per huishouden, per jaar
Gemiddelde kosten voor de verwerking afval: € 120 per huishouden, per jaar
Administratieve kosten: € 10 per huishouden, per jaar$$, 'inline'),
  ('7f289836-e8e6-4ce0-8dbb-c54c55021129', '137eda5a-bf04-404b-969b-7af10af4d66c', $$plan van de wethouder om de huisvuilophaaldienst te automatiseren$$,
   $$economie-havo-2022-iii-huisvuil-ophalen-kan-goedkoper-context3.png$$,
   $$De wethouder van Milieuzaken stelt in de gemeenteraad voor om de huisvuilophaaldienst meer te automatiseren. Daarvoor moet aan de gemeentelijke vuilnisvrachtwagen een technische aanpassing worden aangebracht in de vorm van een automatische grijparm, en de chauffeur moet een speciale training volgen. De wethouder verwacht de volgende veranderingen in de kosten en opbrengsten:
− De constante kosten nemen toe met € 20.000 per jaar voor de technische aanpassing aan de vrachtwagen en de training.
− Na deze automatisering is nog maar één werknemer nodig om de huisvuilroute te rijden in plaats van twee.
− De kans op gezondheidsklachten bij het personeel neemt af. De wethouder legt aan de gemeenteraad uit dat de kostenreductie, in combinatie met de verwachte groei van het aantal huishoudens, ertoe zal leiden dat de huisvuilophaaldienst kostendekkend kan gaan werken. De wethouder gaat ervan uit dat de overige kosten en opbrengsten hetzelfde blijven.$$, 'inline'),
  ('09e4ec02-b18f-4a17-a8b2-439abbd11d15', '137eda5a-bf04-404b-969b-7af10af4d66c', $$inspraakavond: mevrouw van Buren over verzonken kosten en de heer Jastek over externe effecten$$,
   $$economie-havo-2022-iii-huisvuil-ophalen-kan-goedkoper-context4.png$$,
   $$Tijdens een inspraakavond in de gemeente wordt verschillend gedacht over het plan van de wethouder. Mevrouw van Buren stelt dat de gemeente de investering uit moet stellen totdat het nieuwe systeem zich in andere gemeentes voldoende heeft bewezen, om zodoende te voorkomen dat de gemeente te maken krijgt met verzonken kosten. De heer Jastek stelt dat de afgenomen kans op gezondheidsklachten bij personeel leidt tot een daling van de negatieve externe effecten.$$, 'inline'),
  ('1d7aa2c7-2d21-4edd-af69-e7932d96a9e2', '0db85224-2b59-4746-9db3-6a65f600dded', $$na de kredietcrisis eist de ECB minstens 10 eurocent eigen vermogen per euro verleend krediet$$,
   $$economie-havo-2022-iii-banken-buiten-spel-context1.png$$,
   $$Een van de oorzaken van de kredietcrisis in 2008 was dat banken te veel krediet verleenden in verhouding tot hun eigen vermogen. Daardoor hadden banken te weinig reserves om verliezen bij de kredietverlening op te vangen. Na de kredietcrisis stelde de toezichthouder, de Europese Centrale Bank (ECB), strengere eisen aan banken. Een van die eisen is de vermogenseis, die stelt dat banken tegenover elke euro verleend krediet tenminste 10 eurocent eigen vermogen op de balans moeten hebben.$$, 'inline'),
  ('9a31ba2a-8f3f-45bc-a01d-cf5ece2ae9ca', '0db85224-2b59-4746-9db3-6a65f600dded', $$balans van een bank (bedragen × € 1 miljoen)$$,
   $$economie-havo-2022-iii-banken-buiten-spel-context2.png$$,
   $$Een bank heeft de volgende bezittingen en schulden op de balans (bedragen × € 1 miljoen):$$, 'inline'),
  ('0421f0ea-4a28-423d-8fc6-a21bee060476', '0db85224-2b59-4746-9db3-6a65f600dded', $$tabel: balans met verleende kredieten, overige bezittingen, eigen en vreemd vermogen$$,
   $$economie-havo-2022-iii-banken-buiten-spel-context3.png$$,
   $$Bezittingen: Verleende kredieten € 2.000 | Overige bezittingen € 1.000 | totaal € 3.000
Schulden: Eigen Vermogen € 150 | Vreemd Vermogen € 2.850 | totaal € 3.000$$, 'inline'),
  ('c173077d-d712-4b66-bdb3-d5f94b65ddeb', '0db85224-2b59-4746-9db3-6a65f600dded', $$kredietunies: ondernemers lenen aan elkaar zonder bank; asymmetrische informatie$$,
   $$economie-havo-2022-iii-banken-buiten-spel-context4.png$$,
   $$Als gevolg van de strengere eisen neemt de kredietverlening aan het midden- en kleinbedrijf (mkb) door banken sterk af. Omdat het mkb minder bij banken kan lenen, worden zogenaamde kredietunies opgericht. Bij een kredietunie verleent een ondernemer aan een andere ondernemer krediet, zonder tussenkomst van een bank. Hierbij is sprake van asymmetrische informatie.$$, 'inline'),
  ('977227a5-f1a9-409c-a349-24a7bc09b671', '0db85224-2b59-4746-9db3-6a65f600dded', $$investeringsfonds voor het mkb met overheidsgarantie$$,
   $$economie-havo-2022-iii-banken-buiten-spel-context5.png$$,
   $$Ondanks de opkomst van kredietunies hebben veel mkb-ondernemingen moeite om aan krediet te komen ter financiering van hun investeringen. De overheid wil stimuleren dat mkb-ondernemingen blijven investeren, en werkt daarom mee aan de oprichting van een investeringsfonds voor het mkb. Het investeringsfonds wordt gevuld door pensioenfondsen en andere verzekeringsmaatschappijen. Een ondernemer kan voor een deel van zijn investering geld lenen bij dat fonds. De overheid geeft garanties voor terugbetaling aan het investeringsfonds, als ondernemers hun verplichtingen niet kunnen nakomen.$$, 'inline'),
  ('9b197c04-fb01-479f-921e-92c0a53f9749', '8046a11b-8feb-4f72-b22f-1d8ffe84a3fc', $$uit een krant (2015): het Nederlandse overheidstekort kwam in 2013 onder de 3% (zie kader)$$,
   $$economie-havo-2022-iii-het-begrotingstekort-daalt-eindelijk-context1.png$$,
   $$Uit een krant, 2015: In het voorjaar van 2013 voorspelde het Centraal Planbureau (CPB) dat het overheidstekort van Nederland zou uitkomen op 3,1% van het bruto binnenlands product (bbp) in 2013. De voorspelling bleek onjuist, want eind 2013 was het overheidstekort van Nederland weer onder de 3% gekomen. Daarmee voldeed Nederland voor het eerst sinds de economische en financiële crisis weer aan de norm voor het overheidstekort van het Stabiliteits- en Groeipact (SGP) (zie kader).$$, 'inline'),
  ('294e4250-eda8-4417-916c-3f3111c1307d', '8046a11b-8feb-4f72-b22f-1d8ffe84a3fc', $$kader: het Stabiliteits- en Groeipact (SGP) en de boeteclausule$$,
   $$economie-havo-2022-iii-het-begrotingstekort-daalt-eindelijk-context2.png$$,
   $$Het Stabiliteits- en Groeipact (SGP) en de boeteclausule De lidstaten die deel uitmaken van de Economische en Monetaire Unie (EMU) moeten zich vanaf 2013 opnieuw1) houden aan de volgende afspraken:
− Het overheidstekort mag niet meer bedragen dan 3% van het bbp.
− De overheidsschuld mag niet hoger zijn dan 60% van het bbp. Als een lidstaat de beide normen van overheidstekort en overheidsschuld overschrijdt, dan legt de EMU aan de lidstaat een boete op van 0,2% van het bbp van het voorafgaande jaar.
noot 1 De EMU ging tijdens de voorafgaande crisis soepeler om met de normen en legde toen geen boete op.$$, 'inline'),
  ('4c5b575a-af9a-4489-9704-0890dc8a0c19', '8046a11b-8feb-4f72-b22f-1d8ffe84a3fc', $$economische groei boven de trend; overheidsschuld boven de norm, maar geen boete (zie bron 1)$$,
   $$economie-havo-2022-iii-het-begrotingstekort-daalt-eindelijk-context3.png$$,
   $$Vanaf 2014 lag de economische groei in Nederland boven de trendmatige groei. De overheidsschuld als percentage van het bbp kwam in 2013 en 2014 nog steeds ruim boven de norm van het SGP uit (zie bron 1). Ondanks het overschrijden van de norm van de overheidsschuld, heeft Nederland in 2013 en 2014 geen boete van de EMU gehad.$$, 'inline'),
  ('93371796-90e5-47cd-975e-0f42dbf3eacb', '8046a11b-8feb-4f72-b22f-1d8ffe84a3fc', $$uitspraken van Amira en Oscar over de boeteclausule$$,
   $$economie-havo-2022-iii-het-begrotingstekort-daalt-eindelijk-context4.png$$,
   $$In een havo 5-klas bespreken leerlingen de ontwikkeling van het overheidstekort in Nederland en de toepassing van de boeteclausule voor ons land.
− Amira: Had Nederland in 2013 die 3%-norm niet gehaald, dan zou Nederland een boete hebben gekregen van ruim 1,5 miljard euro.
− Oscar: Als we in 2014 een boete opgelegd hadden gekregen, dan zou die boete vanaf 2014 een procyclische werking hebben op de conjunctuur van Nederland.$$, 'inline'),
  ('9ac6dfe1-59da-4d23-9487-e5c017db61ab', '8046a11b-8feb-4f72-b22f-1d8ffe84a3fc', $$Laura: het overheidstekort moet in verband met de vergrijzing verder omlaag$$,
   $$economie-havo-2022-iii-het-begrotingstekort-daalt-eindelijk-context5.png$$,
   $$In de klas wordt gediscussieerd over de ruimte voor nieuwe overheidsuitgaven die ontstaat als het overheidstekort onder de SGP- norm is gedaald. Veel leerlingen vinden dat er dan ruimte ontstaat voor nieuwe overheidsuitgaven. Laura is het daar beslist niet mee eens. Haar standpunt is dat het overheidstekort in verband met de vergrijzing verder moet worden verlaagd.$$, 'inline'),
  ('fa83cafc-0a5b-46fa-aa80-cb9f6040c4d0', '8046a11b-8feb-4f72-b22f-1d8ffe84a3fc', $$economische groei helpt de SGP-norm voor de overheidsschuld te halen$$,
   $$economie-havo-2022-iii-het-begrotingstekort-daalt-eindelijk-context6.png$$,
   $$Een van de voorwaarden van het SGP is erop gericht om de omvang van de overheidsschuld te beheersen. De verwachte economische groei in de jaren na de crisis helpt mee om de norm van het SGP te bereiken. Als de Nederlandse regering erin zou slagen om de overheidsschuld van Nederland niet verder te laten toenemen, dan zal uiteindelijk de norm kunnen worden gehaald.$$, 'inline'),
  ('59c7d51f-7400-4112-8d68-087b2b02e6c6', '8046a11b-8feb-4f72-b22f-1d8ffe84a3fc', $$bron 1: ontwikkeling bbp, overheidsschuld en overheidstekort 2012-2015$$,
   $$economie-havo-2022-iii-het-begrotingstekort-daalt-eindelijk-context7.png$$,
   $$bron 1 Ontwikkeling bbp, overheidsschuld en overheidstekort (x 1 miljard euro)
staafdiagram: 2012: bbp 599 | overheidsschuld 427 | overheidstekort 25
2013 voorspelling: bbp 606 | overheidsschuld 450 | overheidstekort 19
2013 gerealiseerd: bbp 603 | overheidsschuld 443 | overheidstekort 17
2014 voorspelling: bbp 615 | overheidsschuld 459 | overheidstekort 18
2015 voorspelling: bbp 632 | overheidsschuld 471 | overheidstekort 13$$, 'inline'),
  ('c1b97f15-c709-4126-8a5b-ca571b7f5f37', '4f1da54c-a717-4d61-88bf-d94b5f587cd6', $$uit een krant (december 2016): ‘stille’ prijsopdrijvingen door krimpflatie$$,
   $$economie-havo-2022-iii-krimpflatie-context1.png$$,
   $$Uit een krant, december 2016: ‘Stille’ prijsopdrijvingen Een reep chocolade die in gewicht is verlaagd van 225 naar 200 gram, maar nog steeds € 3,49 kost; toiletpapierrollen die 14% minder vellen tellen dan vroeger, maar nog steeds even duur zijn; koffiepads die 0,5 gram minder koffie bevatten, maar waarvoor de consument nog steeds evenveel betaalt. Economen hebben er een naam voor: krimpflatie, een samentrekking van krimp en inflatie. Door de omvang of het gewicht van een product te verlagen, kunnen producenten voorkomen dat zij de prijzen van hun product moeten verhogen vanwege bijvoorbeeld een stijging van de grondstofkosten. Maar, het kan ook een manier zijn om meer winst te maken. De krimpflatie werd ook dit jaar niet meegenomen in het standaardmandje van producten dat het Centraal Bureau voor de Statistiek (CBS) gebruikt om de consumentenprijsindex (CPI) te bepalen. Woordvoerder Jaap Knoop van het CBS: “De consument is de dupe, want krimpflatie zorgt voor een daling van de koopkracht.”$$, 'inline'),
  ('8242a888-f2ac-4975-b364-0a12071ea614', '4f1da54c-a717-4d61-88bf-d94b5f587cd6', $$theeproducent Roy Bos overweegt de inhoud van een doos te verminderen van 20 naar 19 theezakjes$$,
   $$economie-havo-2022-iii-krimpflatie-context2.png$$,
   $$Theeproducent Roy Bos wordt geconfronteerd met een stijging van de grondstofprijs van de theezakjes. Hij overweegt de inhoud van een doos te verminderen van 20 naar 19 theezakjes en de verkoopprijs te handhaven, omdat hij dan nog winst maakt.$$, 'inline'),
  ('3bce7903-f720-4c5b-8d66-cb63d24be391', '4f1da54c-a717-4d61-88bf-d94b5f587cd6', $$concurrent Celine Stevens: prijs verhogen of inhoud verminderen (zie bron 3)$$,
   $$economie-havo-2022-iii-krimpflatie-context3.png$$,
   $$De enige concurrent van Roy Bos, theeproducent Celine Stevens, wordt ook geconfronteerd met een stijging van de inkoopkosten van de grondstof thee. Beide producenten staan voor de keuze om de verkoopprijs te verhogen óf de inhoud van een doos theezakjes te verminderen. De collectieve afzet van theezakjes blijft gelijk, en beide producenten streven naar maximale winst. De keuzes van beide producenten leiden tot een winststijging, zoals blijkt uit de pay-off-matrix (zie bron 3). Celine Stevens zegt hierover: “Er is geen sprake van een gevangenendilemma, en daarom kan ik het beste de inhoud van een doos thee verlagen.”$$, 'inline'),
  ('508d467f-54b8-47d4-aaaf-499c700b124f', '4f1da54c-a717-4d61-88bf-d94b5f587cd6', $$bron 1: consumentenprijzen 2017 gecorrigeerd voor krimpflatie$$,
   $$economie-havo-2022-iii-krimpflatie-context4.png$$,
   $$bron 1 Consumentenprijzen 2017 gecorrigeerd voor krimpflatie
Het CPI zonder correctie van krimpflatie kwam in 2017 uit op 100,3 (2016=100). Het CBS heeft voor het jaar 2017 een inschatting gemaakt van de gevolgen voor het partiële prijsindexcijfer van de verschillende bestedingscategorieën, indien de krimpflatie wel zou worden doorberekend. Daartoe is op productniveau berekend wat de nieuwe prijs had moeten zijn als deze relatief evenveel zou dalen als de omvang of het gewicht van het product.
bestedingscategorieën | partiële prijsindex 2017 na correctie krimpflatie (2016=100) | wegingscoëfficiënt
voedingsmiddelen | 102,1 | 12
alcohol en tabak | 102,5 | 3
kleding en schoenen | 100,6 | 5
huisvesting, water, energie | 100,6 | 26
vervoer en communicatie | 98,1 | 14
recreatie en restaurants | 101,3 | 16
overig | 100,1 | 24
totaal | ……. | 100$$, 'inline'),
  ('5f94b3c9-31c7-4574-b8f1-e2e084b6fb93', '4f1da54c-a717-4d61-88bf-d94b5f587cd6', $$bron 2: gegevens theezakjes van Roy Bos$$,
   $$economie-havo-2022-iii-krimpflatie-context5.png$$,
   $$bron 2 Gegevens theezakjes van Roy Bos
vóór grondstofprijswijziging en inhoudswijziging: inhoud doos 20 theezakjes; afzet 1.500.000 dozen per jaar; kosten per doos: loon € 0,30, verpakking € 0,08, productie € 0,12, grondstoffen € 0,10, overig € 0,06; gemiddelde winst per doos € 0,54; verkoopprijs per doos € 1,20
ná grondstofprijswijziging en inhoudswijziging: inhoud doos 19 theezakjes; er worden per jaar evenveel theezakjes verkocht; de grondstofprijs stijgt met 10%; alle kosten zijn proportioneel variabel, dat wil zeggen dat ze evenredig dalen met het aantal theezakjes; gemiddelde winst per doos …; verkoopprijs per doos € 1,20$$, 'inline'),
  ('7d2f35db-59c1-4c8a-8d74-e296c576a194', '4f1da54c-a717-4d61-88bf-d94b5f587cd6', $$bron 3: pay-off-matrix Roy Bos en Celine Stevens$$,
   $$economie-havo-2022-iii-krimpflatie-context6.png$$,
   $$bron 3 Pay-off-matrix Roy Bos en Celine Stevens: de winststijging per jaar
Roy Bos \ Celine Stevens | verkoopprijs per doos verhogen | inhoud per doos verminderen
verkoopprijs per doos verhogen | 2% ; 2% | 1% ; 6%
inhoud per doos verminderen | 6% ; 1% | 4% ; 4%
Het linkergetal geeft de winststijging per jaar weer voor Roy Bos, het rechtergetal de winststijging per jaar voor Celine Stevens.$$, 'inline'),
  ('986950b7-b76f-4e37-85da-55a378198fd2', 'f8dae0e2-37e6-4033-b4f8-5e92db2379fe', $$uit een tijdschrift: omzet inktpatronen in Europa, kloon-patronen en patenten$$,
   $$economie-havo-2022-iii-inkt-het-zwarte-goud-context1.png$$,
   $$Uit een tijdschrift: In 2018 werd voor € 9,3 miljard aan inktpatronen omgezet in Europa. De omzet in 2021 is 5 procent hoger dan in 2018. De prijzen voor inktpatronen zijn hoog. Consumenten zoeken naar een goedkopere, maar kwalitatief gelijkwaardige vervanging van originele inktpatronen, de zogenaamde ‘kloon-patronen’. De grote fabrikanten doen er alles aan om de ‘namakers’ te weren. Daarom zitten op sommige originele inktpatronen wel veertig tot vijftig patenten. Ook vervalt de garantie op de printer als er geen origineel inktpatroon is gebruikt.$$, 'inline'),
  ('33b68c0b-5ab4-4b2b-a91c-371ba8e59862', 'f8dae0e2-37e6-4033-b4f8-5e92db2379fe', $$Sister is een van de grotere fabrikanten met een omzet van meer dan 4 miljard euro$$,
   $$economie-havo-2022-iii-inkt-het-zwarte-goud-context2.png$$,
   $$Sister is wereldwijd een van de grotere fabrikanten van printers en inktpatronen met een omzet van meer dan 4 miljard euro.$$, 'inline'),
  ('bb348020-f0cc-4975-a304-bd5e46c3cdf6', 'f8dae0e2-37e6-4033-b4f8-5e92db2379fe', $$Inktmarkt.nl biedt kloon-patronen aan voor minder dan 50% van de prijs$$,
   $$economie-havo-2022-iii-inkt-het-zwarte-goud-context3.png$$,
   $$Inktmarkt.nl is aanbieder van kloon-patronen. De marketingdirecteur legt uit waarom de kloon-patronen van Inktmarkt.nl zo populair zijn: “Wij leveren dezelfde kwaliteit inkt tegen minder dan 50% van de prijs van de originele patronen.”$$, 'inline'),
  ('2d498fd8-dc0d-4561-9bc2-c2033c92ce5d', 'f8dae0e2-37e6-4033-b4f8-5e92db2379fe', $$Sister wil Inktmarkt.nl overnemen; melding bij de mededingingsautoriteit$$,
   $$economie-havo-2022-iii-inkt-het-zwarte-goud-context4.png$$,
   $$Sister, met een jaaromzet van 65 miljoen euro op de Nederlandse markt, heeft plannen om de internetwinkel Inktmarkt.nl met een jaaromzet van 20 miljoen euro over te nemen. Inktmarkt.nl verkoopt alleen in Nederland. In bepaalde gevallen moeten overnames verplicht worden aangemeld bij de mededingingsautoriteit.$$, 'inline'),
  ('f7607b06-a6c3-433b-ba20-217b08c917e1', 'f8dae0e2-37e6-4033-b4f8-5e92db2379fe', $$de mededingingsautoriteit kan overnames verbieden om de concurrentie te waarborgen$$,
   $$economie-havo-2022-iii-inkt-het-zwarte-goud-context5.png$$,
   $$De mededingingsautoriteit kan overnames van bedrijven verbieden, om de concurrentie te waarborgen.$$, 'inline'),
  ('7174410b-8ec9-4011-b901-8e5215ceb893', 'f8dae0e2-37e6-4033-b4f8-5e92db2379fe', $$bron 1: marktaandelen van inktpatronen in 2021$$,
   $$economie-havo-2022-iii-inkt-het-zwarte-goud-context6.png$$,
   $$bron 1 Marktaandelen van inktpatronen in procenten van de totale omzet in 2021
| HP | Epson | Canon | Sister | overig
Europa | 25 | 22 | 15 | 15 | 23
de wereld | 15 | 16 | 30 | 20 | 19$$, 'inline'),
  ('5afaeeac-3e53-4a88-86c2-613ec7088b4c', 'f8dae0e2-37e6-4033-b4f8-5e92db2379fe', $$bron 2: aanmelden bij de mededingingsautoriteit ACM$$,
   $$economie-havo-2022-iii-inkt-het-zwarte-goud-context7.png$$,
   $$bron 2 Aanmelden bij de mededingingsautoriteit ACM
De Autoriteit Consument & Markt (ACM) houdt toezicht op de concurrentie tussen bedrijven in Nederland. De ACM kan overnames van bedrijven verbieden om de concurrentie te waarborgen. Bedrijven moeten een overname bij de ACM melden als aan de volgende twee voorwaarden is voldaan:
1 De wereldwijde omzet van de betrokken ondernemingen in een jaar is in totaal meer dan € 113.450.000.
2 Minstens twee van de betrokken ondernemingen hebben binnen Nederland elk een jaaromzet van minimaal € 30 miljoen.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('ddcbb3eb-7274-450d-ab22-dbe91ecba00c', '002fe60a-3c5c-4331-854c-ffeae35c06f6', 1,
   '[{"domain": "Welvaart en groei", "subdomain": "Ongelijkheid en herverdeling"}]'::jsonb,
   '["marginaal tarief", "nivelleren", "denivelleren", "hypotheekrenteaftrek", "indirecte belastingen"]'::jsonb,
   $$Invullen hoe veranderde marginale tarieven en aftrekposten de inkomensverdeling beïnvloeden.$$,
   $$economie-havo-2022-iii-van-drie-naar-twee-schijven-vraag1.png$$, $$Gebruik de tekst en bron 1.
3p 1 Maak van onderstaande zinnen een economisch juiste redenering.
− De inkomstenbelasting is een instrument om de …(1)... inkomens te herverdelen.
− In het nieuwe stelsel …(2)… het marginale tarief van de lage inkomens tot en met € 20.142, …(3)… het marginale tarief van de hoge inkomens vanaf € 68.601, en …(4)… het marginale tarief van de middengroep.
− De aanpassingen van de marginale tarieven hebben een …(5)… effect op de inkomensverdeling.
− De maatregel om de hypotheekrenteaftrek te verlagen naar het tarief in de eerste schijf heeft een …(6)… effect op de inkomensverdeling.
− In het nieuwe belastingstelsel …(7)… de indirecte belastingen.
Kies uit:
Bij (1) primaire / secundaire
Bij (2) stijgt / daalt
Bij (3) stijgt / daalt
Bij (4) stijgt / daalt
Bij (5) denivellerend / nivellerend
Bij (6) denivellerend / nivellerend
Bij (7) stijgen / dalen$$, array['ab222b1e-0804-41c6-b13e-8fa91668bc07', '95a8324c-1309-4919-8ede-a5db33e42dc8', '732d6b5e-79ac-4496-b140-b7dec044c355', 'cc5196a7-8b00-43f1-a462-ad69bb261e61']::uuid[]),
  ('0a19a497-9b7c-4eaa-a398-3722f32de791', '002fe60a-3c5c-4331-854c-ffeae35c06f6', 2,
   '[{"domain": "Welvaart en groei", "subdomain": "Ongelijkheid en herverdeling"}]'::jsonb,
   '["gemiddelde belastingdruk berekenen", "schijventarief", "heffingskorting", "arbeidskorting"]'::jsonb,
   $$Met schijven en heffingskortingen de gemiddelde belastingdruk onder het nieuwe stelsel berekenen.$$,
   $$economie-havo-2022-iii-van-drie-naar-twee-schijven-vraag2.png$$, $$Gebruik bron 1 en 2.
2p 2 Toon aan de hand van een berekening aan of bij een belastbaar inkomen uit arbeid van € 40.000 de gemiddelde belastingdruk onder het nieuwe belastingsysteem is gedaald.$$, array['c3a45791-44b5-4327-9551-b81ab9bc27cf', 'ec046127-6753-4f6c-a290-5502c5543040', 'cc5196a7-8b00-43f1-a462-ad69bb261e61', 'ad8d21ab-7f4d-42fd-a4ab-7fa835d030d6']::uuid[]),
  ('15bbe34d-28e3-4a07-be0e-512c3e628d5f', '002fe60a-3c5c-4331-854c-ffeae35c06f6', 3,
   '[{"domain": "Markt", "subdomain": "Arbeidsmarkt"}]'::jsonb,
   '["vraag naar arbeid", "loonkosten", "arbeidskorting", "reëel arbeidsinkomen"]'::jsonb,
   $$Uitleggen hoe een lagere belasting op arbeid de vraag naar arbeid kan verhogen.$$,
   $$economie-havo-2022-iii-van-drie-naar-twee-schijven-vraag3.png$$, $$2p 3 Leg uit dat de vraag naar arbeid kan stijgen als gevolg van de invoering van het nieuwe belastingstelsel.$$, array['95a8324c-1309-4919-8ede-a5db33e42dc8', '9fc2964d-f810-42d4-a722-bca97f1f4da3']::uuid[]),
  ('7dd2595d-230a-407f-bf82-f5df139d0c33', '002fe60a-3c5c-4331-854c-ffeae35c06f6', 4,
   '[{"domain": "Welvaart en groei", "subdomain": "Arbeidsmarkt en werkloosheid"}]'::jsonb,
