   '[{"domain": "Goede tijden, slechte tijden", "subdomain": "Conjunctuur en conjuncturele verschijnselen"}, {"domain": "Ruilen over de tijd", "subdomain": "De overheid ruilt over de tijd"}]'::jsonb,
   '["inflatie berekenen", "btw-verhoging", "indirecte belastingen", "gewogen gemiddelde"]'::jsonb,
