   '["break-even-afzet", "kostendekkend", "constante kosten", "dekkingsbijdrage"]'::jsonb,
   $$Berekenen hoeveel huishoudens erbij moeten komen om na automatisering kostendekkend te werken.$$,
   $$economie-havo-2022-iii-huisvuil-ophalen-kan-goedkoper-vraag7.png$$, $$3p 7 Met hoeveel huishoudens moet de gemeente groeien om kostendekkend te kunnen werken volgens het automatiseringsplan van de wethouder? Schrijf je berekening op.$$, array['f8692c78-4550-4103-929e-c15f646272a1', 'b46cd341-3ccd-452f-a4b9-7990d97258b3', '7f289836-e8e6-4ce0-8dbb-c54c55021129']::uuid[]),
