   $$economie-havo-2022-iii-het-begrotingstekort-daalt-eindelijk-vraag16.png$$, $$2p 16 Leg uit of de uitspraak van Oscar juist is.$$, array['294e4250-eda8-4417-916c-3f3111c1307d', '93371796-90e5-47cd-975e-0f42dbf3eacb']::uuid[]),
